        ifTheySay: [{ heard: "That's just being a goody-two-shoes.", reply: "A goody-two-shoes follows rules to look good. Zeno is talking about the choice itself being the good — even when nobody sees and no rule exists. Different thing." }],
        integrity: "Do not generate the counterexample. If a model gives you the pushback, you've outsourced the thinking that Zeno said is the only good.",
        aiLab: { setup: "After testing.", childDoes: "Ask: 'Can you find one thing Zeno got wrong?' Don't help — let them search.", evaluate: ["Did they distinguish indifferent from worthless?", "Is the counterexample real or generic?"] },
